import{z as i,x as o,o as e,c as d,q as r,j as n,D as B,d as A,s,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"费率结构","description":"","frontmatter":{"title":"费率结构","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-fee-structure.md","filePath":"quant/cn-fee-structure.md","lastUpdated":1791413859000}'),p={name:"quant/cn-fee-structure.md"};function D(u,E,c,C,m,T){const t=o("Mermaid");return e(),d("div",null,[E[2]||(E[2]=r('<h1 id="费率结构" tabindex="-1">费率结构 <a class="header-anchor" href="#费率结构" aria-label="Permalink to &quot;费率结构&quot;">​</a></h1><div class="epigraph"><p>A 股的费率表不只是价目表，是监管的工具箱：印花税、平今仓、差异化收费，每一项都在改写哪类策略能活，其次才是扣多少钱。</p><footer>—— 据交易所收费与税收政策公开口径整理</footer></div><p><a href="/quant/cn-programmatic-filing">上一课</a>把交易身份报进系统，接下来把账单拆开。一笔 A 股量化交易从委托到清算，扣钱的位置比多数新手清单长得多。<a href="/quant/cn-fees-stamp-duty">交易费用与印花税</a>已写显性费率与印花税沿革，<a href="/quant/fees-compounding">费用对复合收益</a>写了长期复合效应。本课写实践口径：全成本预算怎么编、换手与超额怎么换算、哪些费率要当政策变量读。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>只按「佣金万几」编预算，会系统性高估可上线策略。显性一侧至少有：佣金（通常含代收规费）、印花税（卖出单边）、过户费；衍生品一侧有期货交易所手续费与平今仓加收、期权费用；借贷一侧有融资利息与融券费率（<a href="/quant/cn-margin-lending-structure">融券与转融通</a>讲过券息右尾）；隐性一侧是冲击成本。成本以「单边成本乘换手」的倍数放大：双边总成本千分之二的策略，年换手五十倍就吃掉十个点的费前收益——多数中国量化的超额预算没有这么厚。预算不拆格，就不知道政策调一项费率后哪个策略先死。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成本台账按「显性/隐性 × 现货/期货/期权/借贷」四格编，每格记当期费率与生效日期，政策变动时整格替换而不是手工改几个数。临界换算给一条：设费前年化超额为 \\(\\alpha\\)、双边总成本率为 \\(c\\)、年换手（双边口径）为 \\(t\\)，费后超额约为 \\(\\alpha - ct\\)，可容忍换手上界 \\(t^{\\ast}=\\alpha/c\\)。算 \\(c\\) 用波动日的右尾分位而不用均值——冲击在高波动日右偏，恰是换手最密的时段。</p><p><span class="marginnote">代入数字感受 \\(t^{\\ast}=\\alpha/c\\)：费前年化超额 8%、双边总成本 0.2%，可容忍换手就是 8% ÷ 0.2% = 40 倍，第 41 倍起开始亏超额。若冲击把 \\(c\\) 推到 0.4%，上界立刻砍半到 20 倍——成本翻倍，生存空间减半。</span>执行侧把冲击从预算里买回来：拆单与参与率约束交给执行算法，接口见<a href="/quant/tcost-opt">交易成本感知优化</a>。</p>',8)),(e(),n(l,null,{default:B(()=>[s(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20TRADE%5B%22%E4%B8%80%E7%AC%94%E4%BA%A4%E6%98%93%22%5D%20--%3E%20STOCK%5B%22%E7%8E%B0%E8%B4%A7%EF%BC%9A%E4%BD%A3%E9%87%91%2B%E5%8D%B0%E8%8A%B1%E7%A8%8E%2B%E8%BF%87%E6%88%B7%E8%B4%B9%22%5D%0A%20%20TRADE%20--%3E%20FUT%5B%22%E6%9C%9F%E8%B4%A7%EF%BC%9A%E6%89%8B%E7%BB%AD%E8%B4%B9%2B%E5%B9%B3%E4%BB%8A%E4%BB%93%E5%8A%A0%E6%94%B6%22%5D%0A%20%20TRADE%20--%3E%20OPT%5B%22%E6%9C%9F%E6%9D%83%EF%BC%9A%E6%9D%83%E5%88%A9%E9%87%91%E5%A4%96%E8%B4%B9%E7%94%A8%22%5D%0A%20%20TRADE%20--%3E%20LOAN%5B%22%E5%80%9F%E8%B4%B7%EF%BC%9A%E8%9E%8D%E8%B5%84%E5%88%A9%E6%81%AF%2B%E5%88%B8%E6%81%AF%E5%8F%B3%E5%B0%BE%22%5D%0A%20%20STOCK%20--%3E%20BUDGET%5B%22%E5%B9%B4%E5%8C%96%E6%88%90%E6%9C%AC%E9%A2%84%E7%AE%97%22%5D%0A%20%20FUT%20--%3E%20BUDGET%0A%20%20OPT%20--%3E%20BUDGET%0A%20%20LOAN%20--%3E%20BUDGET%0A%20%20IMP%5B%22%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%EF%BC%9A%E6%B3%A2%E5%8A%A8%E6%97%A5%E5%8F%B3%E5%81%8F%22%5D%20--%3E%20BUDGET%0A%20%20BUDGET%20--%3E%20CALC%5B%22%E8%B4%B9%E5%90%8E%E8%B6%85%E9%A2%9D%20%CE%B1%20%E2%88%92%20ct%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"可以把成本台账想象成超市小票的分栏：现货、期货、期权、借贷各一栏，每栏都标着「这个价从哪天生效」。政策改一项是整栏换价签，不是在收银台上手工抹零——抹零式改数，最容易漏掉跨政策日的回测段。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[A("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"费率结构是监管工具箱。印花税的单边化与税率调整直接改写高换手策略的生存线，历史上每次调整都伴随策略结构迁移；股指期货的平今仓加收改变日内策略的隔夜决策，持仓过夜与否不再只是风险问题；差异化收费按报备的速率画像分层（上一课的报备档案在这里变成定价输入），把高频的边际成本变成合规变量；融资利率与券息把杠杆和空头都变成有持有成本的选择。读懂这一层，政策变动日才能快速重算预算，而不是几周后从净值里反推。一项政策费率变动沿哪条路径、先把哪类策略挤出，可以画成传导图：",-1)),(e(),n(l,null,{default:B(()=>[s(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20POL%5B%22%E6%94%BF%E7%AD%96%E8%B0%83%E6%95%B4%E4%B8%80%E9%A1%B9%E8%B4%B9%E7%8E%87%22%5D%20--%3E%20STAMP%5B%22%E5%8D%B0%E8%8A%B1%E7%A8%8E%EF%BC%9A%E5%8D%96%E5%87%BA%E8%85%BF%E6%88%90%E6%9C%AC%E5%8F%98%E5%8C%96%22%5D%0A%20%20POL%20--%3E%20PING%5B%22%E5%B9%B3%E4%BB%8A%E4%BB%93%EF%BC%9A%E6%97%A5%E5%86%85%E5%B9%B3%E4%BB%93%E5%8A%A0%E6%94%B6%22%5D%0A%20%20POL%20--%3E%20DIFF%5B%22%E5%B7%AE%E5%BC%82%E5%8C%96%E6%94%B6%E8%B4%B9%EF%BC%9A%E6%8C%89%E6%8A%A5%E6%92%A4%E7%94%BB%E5%83%8F%E5%88%86%E5%B1%82%22%5D%0A%20%20STAMP%20--%3E%20HI%5B%22%E9%AB%98%E6%8D%A2%E6%89%8B%E7%AD%96%E7%95%A5%20t*%20%E4%B8%8B%E9%99%8D%22%5D%0A%20%20PING%20--%3E%20IN%5B%22%E6%97%A5%E5%86%85%E6%9C%9F%E8%B4%A7%E7%AD%96%E7%95%A5%E9%9A%94%E5%A4%9C%E5%86%B3%E7%AD%96%E9%87%8D%E7%AE%97%22%5D%0A%20%20DIFF%20--%3E%20HF%5B%22%E9%AB%98%E9%A2%91%E6%8A%A5%E6%92%A4%E8%BE%B9%E9%99%85%E6%88%90%E6%9C%AC%E4%B8%8A%E5%8D%87%22%5D%0A%20%20HI%20--%3E%20OUT%5B%22%E9%A2%84%E7%AE%97%E6%9C%80%E8%96%84%E7%9A%84%E7%AD%96%E7%95%A5%E5%85%88%E8%A2%AB%E6%8C%A4%E5%87%BA%22%5D%0A%20%20IN%20--%3E%20OUT%0A%20%20HF%20--%3E%20OUT%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[A(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=r('<p><span class="marginnote">印花税现为卖出单边征收，经 2023 年下调后为万分之五；它是预算表里变动最频繁的一格，台账里务必记生效日期，回测跨政策日要分段取费率。</span></p><p><span class="marginnote">「平今仓」就是今天开、今天平的仓位。交易所对这种日内平仓在正常手续费之外再加收一笔，等于专门给日内炒单上税；于是「当天平还是持仓过夜」从一个风控选择，变成要算钱的成本决策。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>各项税率费率随监管与券商协议移动，本课不给跨期数字承诺；不写返佣与费率套利类安排；冲击成本的建模方法在执行课程展开，本课只留预算接口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>全成本预算按显性/隐性乘四类工具分格，每格记当期费率与生效日期。</li><li>可容忍换手上界 \\(t^{\\ast}=\\alpha/c\\)；双边成本千二、年换手五十倍即吃掉十个点费前收益。</li><li>费率是监管工具：印花税、平今仓、差异化收费都在改写策略结构，不只是扣钱。</li><li>出处：交易所与税务部门当期收费口径；显性费率沿革见<a href="/quant/cn-fees-stamp-duty">交易费用与印花税</a>。</li></ul>',6))])}const F=i(p,[["render",D]]);export{f as __pageData,F as default};
